/**
 * Execute a JSON-RPC 2.0 request against the MCP server
 * @summary Call MCP tool
 */
export const getCallMcpToolUrl = () => {
  return `/api/cognee/mcp`;
};

export const callMcpTool = async (
  mcpRequest: McpRequest,
  options?: RequestInit,
): Promise<McpResponse> => {
  return customFetch<McpResponse>(getCallMcpToolUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(mcpRequest),
  });
};

export const getCallMcpToolMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof callMcpTool>>,
    TError,
    { data: BodyType<McpRequest> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof callMcpTool>>,
  TError,
  { data: BodyType<McpRequest> },
  TContext
> => {
  const mutationKey = ["callMcpTool"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof callMcpTool>>,
    { data: BodyType<McpRequest> }
  > = (props) => {
    const { data } = props ?? {};

    return callMcpTool(data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type CallMcpToolMutationResult = NonNullable<
  Awaited<ReturnType<typeof callMcpTool>>
>;
export type CallMcpToolMutationBody = BodyType<McpRequest>;
export type CallMcpToolMutationError = ErrorType<unknown>;

/**
 * @summary Call MCP tool
 */
export const useCallMcpTool = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof callMcpTool>>,
    TError,
    { data: BodyType<McpRequest> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationResult<
  Awaited<ReturnType<typeof callMcpTool>>,
  TError,
  { data: BodyType<McpRequest> },
  TContext
> => {
  return useMutation(getCallMcpToolMutationOptions(options));
};

