/**
 * Returns n-hop neighbourhood subgraph for a species node
 * @summary Species graph context
 */
export const getGetKgSpeciesContextUrl = (
  taxonKey: number,
  params?: GetKgSpeciesContextParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/kg/species/${taxonKey}/context?${stringifiedParams}`
    : `/api/kg/species/${taxonKey}/context`;
};

